#include <stdio.h>

struct Cat {
    char name[20];
    int fish;
};

void feed(struct Cat *c, int n) {
    c->fish = c->fish + n;
}

int main(void) {
    struct Cat a = {"小橘", 3};

    feed(&a, 5);
    printf("%s 吃了 %d 条喵\n", a.name, a.fish);
    return 0;
}

#include <stdio.h>

struct Cat {
    char name[20];
    int fish;
};

int main(void) {
    struct Cat cats[3] = {
        {"小橘", 3},
        {"狸花", 5},
        {"大肥鱼", 9}
    };
    struct Cat *p = cats;
    int total = 0;

    for (int i = 0; i < 3; i++) {
        total = total + p->fish;
        p++;
    }
    printf("一共 %d 条喵\n", total);
    return 0;
}
